import 'package:flutter/material.dart';import 'package:flutter_riverpod/flutter_riverpod.dart';import '../../../core/providers/app_providers.dart';
class BreedLibraryScreen extends ConsumerStatefulWidget{const BreedLibraryScreen({super.key});@override ConsumerState<BreedLibraryScreen> createState()=>_BreedLibraryScreenState();}
class _BreedLibraryScreenState extends ConsumerState<BreedLibraryScreen>{String species='Dog',query='';static const dogs=['Labrador Retriever','Golden Retriever','German Shepherd','Poodle','French Bulldog','Beagle','Dachshund','Mixed breed'];static const cats=['Domestic Shorthair','Domestic Longhair','Maine Coon','Siamese','Ragdoll','Persian','Bengal','Mixed breed'];@override Widget build(BuildContext context){final c=ref.watch(appControllerProvider);final items=(species=='Dog'?dogs:cats).where((e)=>e.toLowerCase().contains(query.toLowerCase())).toList();return Scaffold(appBar:AppBar(title:const Text('Breed library')),body:ListView(padding:const EdgeInsets.all(16),children:[SegmentedButton<String>(segments:const[ButtonSegment(value:'Dog',label:Text('Dogs')),ButtonSegment(value:'Cat',label:Text('Cats'))],selected:{species},onSelectionChanged:(v)=>setState(()=>species=v.first)),const SizedBox(height:12),TextField(onChanged:(v)=>setState(()=>query=v),decoration:const InputDecoration(prefixIcon:Icon(Icons.search),hintText:'Search breeds')),const SizedBox(height:12),const Text('Starter directory · individual pets vary. Breed descriptions are not a substitute for meeting and assessing an individual animal.'),const SizedBox(height:10),...items.map((b){final id='breed-${species.toLowerCase()}-${b.toLowerCase().replaceAll(' ','-')}';final saved=c.items('favorites').any((e)=>e['id']==id);return Card(child:ListTile(title:Text(b),subtitle:const Text('Breed overview · care considerations'),trailing:IconButton(icon:Icon(saved?Icons.bookmark:Icons.bookmark_border),onPressed:()=>saved?c.delete('favorites',id):c.save('favorites',{'id':id,'contentId':id,'contentType':'breed','title':b,'species':species,'createdAt':DateTime.now().toIso8601String()})),onTap:()=>showModalBottomSheet(context:context,builder:(ctx)=>Padding(padding:const EdgeInsets.all(22),child:Column(mainAxisSize:MainAxisSize.min,crossAxisAlignment:CrossAxisAlignment.start,children:[Text(b,style:Theme.of(context).textTheme.titleLarge),const SizedBox(height:10),const Text('Breed characteristics vary by individual, lineage, health, environment and early experiences. Do not assume temperament, exercise needs, size or health outcomes from a breed label alone.'),const SizedBox(height:12),TextButton(onPressed:()=>Navigator.pop(ctx),child:const Text('Close'))]))));})]));}}
